import {ProductionPreview} from './preview.js';
import {GPUMaterialBaker} from './gpu.js';
import {decodeMaterialPack,MAPS} from './pack.js';
import {loadProductionMaterial,MATERIAL_CACHE} from './loader.js';
import {BUILDING_ZONES,buildingMaterialRecipe,BUILDING_MATERIAL_SCHEMA} from '../city/building-material.js';
const $=id=>document.getElementById(id),preview=new ProductionPreview();let customRecipe=null;let catalog,baker,worker,latestPack,gpuResult,cpuPack,sequence=0,busy=false;const rows={};
const ms=v=>Number.isFinite(v)?v.toFixed(1)+' ms':'—',size=v=>(v/(1024*1024)).toFixed(2)+' MiB';
function state(message){$('status').textContent=message;}
function controls(value){busy=value;document.body.dataset.busy=String(value);for(const b of document.querySelectorAll('[data-action]'))b.disabled=value;for(const id of ['asset','resolution'])$(id).disabled=value;}
function recipe(){return customRecipe||entry().recipe;}
function entry(){return catalog.entries.find(e=>e.id===$('asset').value);}
function record(path,data){rows[path]=data;$('results').replaceChildren();for(const [name,r]of Object.entries(rows)){const tr=document.createElement('tr');for(const value of [name,r.workload,ms(r.setupMs),ms(r.synthesisMs),ms(r.mipMs),ms(r.readbackMs),ms(r.loadMs),ms(r.uploadMs),ms(r.totalMs)]){const td=document.createElement('td');td.textContent=value;tr.append(td);}$('results').append(tr);}document.body.dataset.metrics=JSON.stringify(rows);}
function describe(pack,source){latestPack=pack;const bytes=Object.values(pack.maps).flat().reduce((n,l)=>n+l.data.byteLength,0);$('memory').textContent=`${source} · ${pack.maps.color[0].width} × ${pack.maps.color[0].height} atlas · ${pack.maps.color.length} mip levels · ${size(bytes)} GPU map payload`;$('path').textContent=source;}
async function action(fn){if(busy)return;controls(true);delete document.body.dataset.error;try{await fn();if(document.body.dataset.error)throw Error(document.body.dataset.error);document.body.dataset.ready='true';}catch(e){state(e.message);document.body.dataset.error=e.message;console.error(e);}finally{controls(false);}}
async function load(useCache){customRecipe=null;$('recipeName').textContent='Published catalog recipe';const start=performance.now();state('Loading pregenerated pack · no synthesis or mip baking on this client…');const result=await loadProductionMaterial(entry(),{useCache}),uploadMs=await preview.apply(result.pack);describe(result.pack,result.source);record(useCache?'Download / cache':'Forced download',{workload:`8 zones / ${entry().tileSize}px`,loadMs:result.timings.totalMs,uploadMs,totalMs:performance.now()-start});$('payload').textContent=`${size(result.payloadBytes)} downloaded/cached → ${size(result.pack.bytes.byteLength)} decoded`;state('Ready · '+result.source+' · checksum verified · zero client synthesis');}
function cpuBake(recipe,n){return new Promise((resolve,reject)=>{worker?.terminate();worker=new Worker(new URL('./cpu-worker.js',import.meta.url),{type:'module'});const id=++sequence;worker.onmessage=({data})=>{if(data.id!==id)return;if(data.error)reject(Error(data.error));else if(data.bytes)resolve(data);else state('CPU worker bake · '+Math.round(data.progress*100)+'%');};worker.onerror=e=>reject(Error(e.message));worker.postMessage({id,recipe,size:n});});}
async function cpu(){const start=performance.now(),n=Number($('resolution').value);state('Starting CPU authoring worker…');const result=await cpuBake(recipe(),n);cpuPack=decodeMaterialPack(result.bytes);const uploadMs=await preview.apply(cpuPack);describe(cpuPack,'CPU authoring worker');record('CPU bake',{workload:`8 zones / ${n}px`,synthesisMs:result.timings.synthesisMs,mipMs:result.timings.mipMs,loadMs:result.timings.packMs,uploadMs,totalMs:performance.now()-start});state('CPU pack complete · no main-thread synthesis');}
async function gpu(){const start=performance.now(),n=Number($('resolution').value);state('Compiling / dispatching WebGPU material kernels…');gpuResult?.dispose();gpuResult=await baker.bake(recipe(),n);const uploadMs=await preview.applyGPU(gpuResult);latestPack=null;record('GPU bake / '+(gpuResult.timings.initMs>0?'cold':'warm'),{workload:`8 zones / ${n}px`,setupMs:gpuResult.timings.initMs,synthesisMs:gpuResult.timings.synthesisMs,mipMs:gpuResult.timings.mipMs,uploadMs,totalMs:performance.now()-start});$('path').textContent='GPU compute → GPU textures';$('memory').textContent=`GPU-resident preview · ${n*4} × ${n*2} atlas · ${gpuResult.levels.length} mip levels · no texture readback`;$('payload').textContent='No network or CPU pixel baking in this path';state('GPU preview ready · height, normals and semantic mips generated on GPU');}
async function readback(){delete document.body.dataset.parity;if(!gpuResult)throw Error('Run the GPU bake first');state('Reading GPU maps for export / parity measurement…');const result=await gpuResult.readback(),pack=decodeMaterialPack(result.bytes);describe(pack,'GPU export / readback');record('GPU export readback',{workload:`8 zones / ${gpuResult.size}px`,readbackMs:result.timings.readbackMs,loadMs:result.timings.packMs,totalMs:result.timings.readbackMs+result.timings.packMs});if(cpuPack&&cpuPack.maps.color[0].width===pack.maps.color[0].width&&JSON.stringify(cpuPack.manifest.recipe)===JSON.stringify(pack.manifest.recipe)){const report={};for(const id of MAPS){let sum=0,max=0,count=0;for(let level=0;level<pack.maps[id].length;level++){const a=cpuPack.maps[id][level].data,b=pack.maps[id][level].data;for(let i=0;i<a.length;i++){const delta=Math.abs(a[i]-b[i]);sum+=delta;max=Math.max(max,delta);}count+=a.length;}report[id]={meanByteError:sum/count,maxByteError:max,mipLevels:pack.maps[id].length};}$('parity').textContent=Object.entries(report).map(([k,v])=>`${k}: mean ${v.meanByteError.toFixed(4)} / max ${v.maxByteError} byte steps`).join(' · ');document.body.dataset.parity=JSON.stringify(report);}else $('parity').textContent='Run CPU and GPU at the same resolution and recipe to compare floating-point output.';state('GPU readback pack ready for download');}
async function download(){if(!latestPack&&gpuResult)await readback();if(!latestPack)throw Error('Load/bake a CPU pack or read back the GPU result first');const url=URL.createObjectURL(new Blob([latestPack.bytes],{type:'application/octet-stream'})),a=document.createElement('a');a.href=url;a.download='aether-production-material.amp';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);state('Versioned material pack exported');}
for(const [i,name]of BUILDING_ZONES.entries()){const o=document.createElement('option');o.value=i;o.textContent=name;$('zone').append(o);}$('zone').onchange=()=>preview.zone($('zone').value);$('channel').onchange=()=>preview.inspect($('channel').value);$('light').onchange=()=>preview.light($('light').value);
$('import').onclick=()=>$('recipeFile').click();$('recipeFile').onchange=()=>action(async()=>{try{const file=$('recipeFile').files[0];if(!file)return;if(file.size>1024*1024)throw Error('Recipe is too large');const raw=JSON.parse(await file.text());if(raw.schema!==BUILDING_MATERIAL_SCHEMA)throw Error('Choose an exported building material recipe');customRecipe=buildingMaterialRecipe(raw);$('resolution').value=String(customRecipe.resolution);$('recipeName').textContent='Custom recipe / '+customRecipe.seed;state('Recipe imported · choose CPU or GPU to produce a runtime pack');}finally{$('recipeFile').value='';}});
$('download').onclick=()=>action(()=>load(false));$('cached').onclick=()=>action(()=>load(true));$('cpu').onclick=()=>action(cpu);$('gpu').onclick=()=>action(gpu);$('readback').onclick=()=>action(readback);$('export').onclick=()=>action(download);$('clear').onclick=()=>action(async()=>{await caches.delete(MATERIAL_CACHE);state('Production material Cache Storage cleared');});$('asset').onchange=()=>action(()=>load(true));
try{controls(true);catalog=await(await fetch(new URL('./catalog.json',import.meta.url),{cache:'no-store'})).json();if(catalog.schema!=='aether.material-catalog/1')throw Error('Unsupported material catalog');for(const e of catalog.entries){const o=document.createElement('option');o.value=e.id;o.textContent=e.label;$('asset').append(o);}await preview.init($('viewport'));baker=new GPUMaterialBaker(preview.device);const info=preview.device.adapterInfo||preview.renderer.backend.adapter?.info;$('adapter').textContent=info?.description||info?.device||info?.vendor||'WebGPU adapter (details hidden)';controls(false);await action(()=>load(true));}catch(e){state(e.message);document.body.dataset.error=e.message;console.error(e);controls(false);}
window.addEventListener('pagehide',()=>{worker?.terminate();gpuResult?.dispose();preview.dispose();},{once:true});
